-- Source SHA256: 89fbe1208d58503ecee12c77057dec08530553ed0b93afccb00bf3a3720fbd30
-- Administrator credentials and Flyway history are intentionally not imported.
-- Existing journal data is authoritative: seed only an entirely empty table.
SET LOCAL standard_conforming_strings = on;
LOCK TABLE journals IN SHARE ROW EXCLUSIVE MODE;
DO $nvuc_seed$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM journals) THEN
        PERFORM setval(pg_get_serial_sequence('journals', 'id'),
                       (SELECT max(id) FROM journals), true);
    ELSE
        RAISE NOTICE 'Journal snapshot skipped: journals already contains data';
    END IF;
END
$nvuc_seed$;
